# -*- coding: utf-8 -*-
"""Sistemas Operacionais (SO) — cota 14."""
from comum import Q

E = "SO"
QUESTOES = [
    Q(E, "04", 8, sub="8.5", pai="ESP-SO-0010", k="so-sjf", tags=["calculo"],
      enun="Quatro processos chegam no instante 0, nesta ordem, com os seguintes tempos de CPU (bursts): P1 = 6, P2 = 8, P3 = 7 e P4 = 3. Os tempos médios de espera obtidos com os algoritmos SJF não preemptivo e FCFS são, respectivamente,",
      alts=["7,0 e 10,25.",
            "7,0 e 7,0.",
            "10,25 e 7,0.",
            "6,0 e 10,25.",
            "8,0 e 12,25."],
      gab="A",
      com="**Gabarito: A.**\n\n- **SJF**: ordem P4 (3), P1 (6), P3 (7), P2 (8). Esperas: P4 = 0, P1 = 3, P3 = 9, P2 = 16 → 28 ÷ 4 = **7,0**.\n- **FCFS**: ordem P1, P2, P3, P4. Esperas: 0, 6, 14, 21 → 41 ÷ 4 = **10,25**.\n\n(B) Repete o SJF para os dois. (C) Inverte os algoritmos. (D) 6,0 não corresponde a nenhuma ordem válida dos bursts. (E) Soma os bursts ao tempo de espera de forma indevida. O SJF é ótimo para o tempo médio de espera.\n\nConta conferida em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 8, sub="8.5", pai="ESP-SO-0010", k="so-rr", tags=["calculo"], dif=3,
      enun="Três processos chegam no instante 0, na ordem P1, P2 e P3, com bursts de 10, 4 e 6 unidades de tempo. Com escalonamento Round-Robin de quantum igual a 4 e desprezando o tempo de troca de contexto, o tempo médio de espera é de aproximadamente",
      alts=["4,67.",
            "6,00.",
            "8,00.",
            "8,67.",
            "10,00."],
      gab="D",
      com="**Gabarito: D.** Gantt: P1 (0–4), P2 (4–8, termina), P3 (8–12), P1 (12–16), P3 (16–18, termina), P1 (18–20, termina). Espera = término − burst: P1 = 20 − 10 = 10; P2 = 8 − 4 = 4; P3 = 18 − 6 = 12. Média = 26 ÷ 3 ≈ **8,67**.\n\n(A) 4,67 é o SJF (P2, P3, P1). (C) 8,00 é o FCFS — neste caso o RR espera um pouco mais que o FCFS, mas melhora o tempo de resposta. (B) e (E) não correspondem a nenhum dos algoritmos.\n\nSimulação em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 8, sub="8.5", pai="ESP-SO-0010", k="so-srtf", tags=["calculo"], dif=3,
      enun="Considere os processos a seguir, com instante de chegada e tempo de CPU:\n\n| Processo | Chegada | Burst |\n|---|---|---|\n| P1 | 0 | 8 |\n| P2 | 1 | 4 |\n| P3 | 2 | 9 |\n| P4 | 3 | 5 |\n\nCom o algoritmo SRTF (SJF preemptivo), o tempo médio de espera é",
      alts=["8,75.",
            "7,75.",
            "6,50.",
            "5,25.",
            "9,00."],
      gab="C",
      com="**Gabarito: C.** SRTF: P1 (0–1); em t=1 chega P2 (4 < 7 restantes de P1) e preempta: P2 (1–5); depois P4 (5–10), P1 (10–17), P3 (17–26). Esperas (término − chegada − burst): P1 = 17 − 0 − 8 = 9; P2 = 5 − 1 − 4 = 0; P3 = 26 − 2 − 9 = 15; P4 = 10 − 3 − 5 = 2. Média = 26 ÷ 4 = **6,5**.\n\n(A) 8,75 é o FCFS. (B) 7,75 é o SJF **não** preemptivo (P1, P2, P4, P3). (D) e (E) não correspondem a nenhuma ordem válida.\n\nSimulação em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 8, sub="8.5", pai="ESP-SO-0012", k="so-escalonamento-correta",
      enun="Sobre algoritmos de escalonamento de CPU, é correto afirmar:",
      alts=["o FCFS é preemptivo e elimina o efeito comboio.",
            "o escalonamento por prioridade pode causar inanição (starvation), que é mitigada pela técnica de envelhecimento (aging).",
            "o SJF não preemptivo dispensa qualquer estimativa do tempo de CPU dos processos.",
            "no Round-Robin, um quantum muito pequeno reduz o número de trocas de contexto.",
            "as múltiplas filas com realimentação mantêm cada processo fixo na fila em que entrou."],
      gab="B",
      com="**Gabarito: B.** No escalonamento por prioridade, processos de baixa prioridade podem esperar indefinidamente (**starvation**); o **aging** aumenta a prioridade de quem espera muito.\n\n(A) FCFS é não preemptivo e **sofre** o efeito comboio. (C) O SJF exige prever o burst. (D) Quantum muito pequeno **aumenta** as trocas de contexto (overhead). (E) Na realimentação (feedback) os processos **mudam** de fila conforme o comportamento; fixos ficam nas múltiplas filas simples."),

    Q(E, "04", 9, sub="9.5", pai="ESP-SO-0015", k="so-paginas", tags=["calculo"], dif=3,
      enun="Um processo gera a sequência de referências a páginas 2, 3, 2, 1, 5, 2, 4, 5, 3, 2, 5, 2, com 3 quadros inicialmente vazios. Os números de faltas de página com os algoritmos FIFO, LRU e Ótimo são, respectivamente,",
      alts=["9, 7 e 6.",
            "7, 9 e 6.",
            "9, 6 e 7.",
            "8, 7 e 6.",
            "9, 7 e 5."],
      gab="A",
      com="**Gabarito: A.**\n\n- **FIFO**: faltas em 2, 3, 1, 5 (sai 2), 2 (sai 3), 4 (sai 1), 3 (sai 5), 5 (sai 2), 2 (sai 4) → **9**.\n- **LRU**: faltas em 2, 3, 1, 5 (sai 3), 4 (sai 1), 3 (sai 2), 2 (sai 4) → **7**.\n- **Ótimo**: faltas em 2, 3, 1, 5 (sai 1, que não será mais usada), 4 (sai 2, cujo próximo uso é o mais distante), 2 (sai 3 ou 4, que não serão mais usadas) → **6**.\n\n(B) Inverte FIFO e LRU. (C) Inverte LRU e Ótimo; o Ótimo nunca tem mais faltas que o LRU. (D) e (E) Erram uma das contagens.\n\nSimulação em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 9, sub="9.3", pai="ESP-SO-0014", k="so-traducao", tags=["calculo"],
      enun="Em um sistema com páginas de 1 KB (1.024 bytes), o processo acessa o endereço lógico 3.300. A tabela de páginas indica que a página correspondente está carregada no quadro 7. O endereço físico gerado é",
      alts=["3.307.",
            "7.228.",
            "7.396.",
            "10.468.",
            "3.300."],
      gab="C",
      com="**Gabarito: C.** Página = ⌊3.300 ÷ 1.024⌋ = 3; deslocamento = 3.300 − 3 × 1.024 = 228. Endereço físico = quadro × tamanho + deslocamento = 7 × 1.024 + 228 = **7.396**.\n\n(A) Soma o número do quadro ao endereço lógico. (B) Usa 1.000 em vez de 1.024 bytes por página. (D) Soma 7 × 1.024 ao endereço lógico inteiro, esquecendo de separar página e deslocamento. (E) Ignora a tradução.\n\nConta conferida em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 8, sub="8.6", pai="ESP-SO-0011", k="so-banqueiro", tags=["calculo"], dif=3,
      enun="Um sistema tem 14 unidades de um único tipo de recurso e usa o algoritmo do banqueiro. O estado atual é:\n\n| Processo | Máximo | Alocado |\n|---|---|---|\n| P0 | 8 | 3 |\n| P1 | 6 | 2 |\n| P2 | 9 | 4 |\n| P3 | 4 | 2 |\n\nÉ correto afirmar que o estado é",
      alts=["inseguro, pois há apenas 3 unidades disponíveis e nenhum processo consegue terminar.",
            "seguro, e a sequência <P0, P1, P2, P3> é uma sequência segura.",
            "seguro, e a sequência <P2, P3, P0, P1> é uma sequência segura.",
            "seguro, e a sequência <P3, P0, P1, P2> é uma sequência segura.",
            "inseguro, e portanto já está em deadlock."],
      gab="D",
      com="**Gabarito: D.** Alocado = 3 + 2 + 4 + 2 = 11 → disponível = 3. Necessidades (máx − aloc): P0 = 5, P1 = 4, P2 = 5, P3 = 2. P3 (2 ≤ 3) termina e devolve → 5; P0 (5 ≤ 5) → 8; P1 (4) → 10; P2 (5) → 14. **<P3, P0, P1, P2>** é segura.\n\n(A) P3 consegue terminar com as 3 disponíveis. (B) P0 precisa de 5 e só há 3. (C) P2 precisa de 5 e só há 3. (E) Estado inseguro não é sinônimo de deadlock — e o estado é seguro.\n\nVerificado em `tools/verificacao/agente4/verif_so.py`."),

    Q(E, "04", 12, sub="12.4", pai="ESP-SO-0032", k="so-umask", tags=["calculo"],
      enun="Em um servidor Oracle Linux, um administrador executa `umask 007` e, em seguida, cria o arquivo `extrato.csv` com `touch` e o diretório `relatorios` com `mkdir`. As permissões resultantes são, respectivamente,",
      alts=["rw-rw-r-- e rwxrwxr-x.",
            "rwxrwx--- e rwxrwx---.",
            "rw-rw---- e rwxrwx---.",
            "rw-r----- e rwxr-x---.",
            "---rw-rw- e ---rwxrwx."],
      gab="C",
      com="**Gabarito: C.** Arquivos partem de 666 e diretórios de 777; a umask **retira** bits: 666 − 007 → **660** (rw-rw----) e 777 − 007 → **770** (rwxrwx---).\n\n(A) Corresponde à umask 002. (B) Arquivos comuns não recebem x por padrão. (D) Corresponde à umask 027. (E) Interpreta a umask como as permissões concedidas.\n\nExecutado em bash (`umask 007; touch; mkdir; stat`) em `tools/verificacao/agente4/verif_so.sh`."),

    Q(E, "04", 12, sub="12.4", pai="ESP-SO-0028", k="so-sgid", mv="E",
      enun="Para uma pasta compartilhada pela equipe de câmbio, o administrador executou `chown root:cambio /srv/cambio` e `chmod 2775 /srv/cambio`. Ao listar o diretório com `ls -ld`, as permissões exibidas e o efeito do bit especial são:",
      alts=["drwxrwsr-x; arquivos criados dentro do diretório herdam o grupo cambio.",
            "drwsrwxr-x; os programas do diretório executam com os privilégios do root.",
            "drwxrwxr-t; só o dono de cada arquivo pode apagá-lo.",
            "drwxrwSr-x; o diretório perde a permissão de execução para o grupo.",
            "-rwxrwsr-x; o diretório passa a ser tratado como arquivo executável."],
      gab="A",
      com="**Gabarito: A.** 2775 = SGID (2000) + rwxrwxr-x. O SGID aparece como **s** no x do grupo (`drwxrwsr-x`) e, em diretório, faz os arquivos criados **herdarem o grupo do diretório** — útil para pastas de equipe.\n\n(B) Descreve o SUID (4000), que em diretório não tem efeito no Linux. (C) Descreve o sticky bit (1000). (D) O `S` maiúsculo só apareceria sem o x do grupo; aqui o x existe. (E) O primeiro caractere `d` indica diretório.\n\nExecutado em bash em `tools/verificacao/agente4/verif_so.sh`."),

    Q(E, "04", 12, sub="12.3", pai="ESP-SO-0030", k="so-pipe-shell", dif=3,
      enun="Considere o comando a seguir, executado em um servidor Red Hat Enterprise Linux:\n\n```bash\ncut -d: -f7 /etc/passwd | sort | uniq -c | sort -rn | head -1\n```\n\nEle exibe",
      alts=["o primeiro usuário cadastrado em /etc/passwd e o seu shell.",
            "o shell de login mais usado entre as contas e quantas contas o utilizam.",
            "o número total de linhas de /etc/passwd.",
            "os usuários sem senha definida, ordenados pelo UID.",
            "o maior UID do sistema."],
      gab="B",
      com="**Gabarito: B.** `cut -d: -f7` extrai o 7º campo (shell); `sort` agrupa iguais; `uniq -c` conta cada um; `sort -rn` ordena pela contagem decrescente; `head -1` mostra o primeiro: o **shell mais usado e sua quantidade**.\n\n(A) Não há seleção por ordem de cadastro. (C) Contaria linhas com `wc -l`. (D) Senhas ficam em /etc/shadow, e o campo 7 é o shell. (E) O UID é o campo 3.\n\nExecutado com um /etc/passwd de exemplo em `tools/verificacao/agente4/verif_so.sh`."),

    Q(E, "04", 11, sub="11.6", pai="ESP-SO-0024", k="so-gpo-enforced", dif=3,
      enun="No domínio `banco.local`, uma GPO vinculada ao domínio define o papel de parede corporativo e está marcada como **Imposta (Enforced)**. A UO Agências tem **Bloquear herança** habilitado e uma GPO própria que define outro papel de parede. Para um usuário da UO Agências, é correto afirmar que",
      alts=["prevalece a GPO da UO, pois o bloqueio de herança impede a aplicação de qualquer GPO superior.",
            "prevalece a GPO do domínio, pois uma GPO imposta não pode ser bloqueada e vence as configurações conflitantes de níveis inferiores.",
            "nenhuma das duas é aplicada, por haver conflito.",
            "prevalece a política local do computador, que é a última processada.",
            "prevalece a GPO do site, por ser processada depois do domínio."],
      gab="B",
      com="**Gabarito: B.** A ordem normal é LSDOU e a última aplicada vence, mas **Enforced vence Block Inheritance**: a GPO imposta não pode ser bloqueada e prevalece sobre GPOs conflitantes de níveis inferiores.\n\n(A) Seria verdade se a GPO do domínio não estivesse imposta. (C) Conflitos são resolvidos pela precedência, não anulam as GPOs. (D) A política local é a **primeira** processada (L de LSDOU). (E) O site é processado **antes** do domínio."),

    Q(E, "04", 11, sub="11.3", pai="ESP-SO-0023", k="so-ad-uo", mv="E",
      enun="No Active Directory, o contêiner usado dentro de um domínio para organizar objetos por departamento, delegar a administração a um grupo de suporte local e vincular GPOs, mas que não é entidade de segurança (não recebe permissões nem entra em ACL), é a",
      alts=["floresta.",
            "árvore.",
            "unidade organizacional (UO).",
            "grupo de segurança global.",
            "site."],
      gab="C",
      com="**Gabarito: C.** A **UO** organiza objetos dentro do domínio, permite **delegar administração** e **vincular GPOs**, e não é entidade de segurança.\n\n(A) Floresta é o limite de segurança, com esquema e catálogo global comuns. (B) Árvore é um conjunto de domínios em espaço de nomes DNS contíguo. (D) Grupos de segurança **recebem** permissões e não recebem vínculo de GPO. (E) Site representa a topologia física para replicação e autenticação."),

    Q(E, "04", 11, sub="11.7", k="so-powershell", tags=["nao_executado"],
      enun="Em um Windows Server 2022, um administrador quer listar apenas os serviços que estão parados e cujo tipo de inicialização é automático. O comando PowerShell adequado é",
      alts=["`Get-Service | Where-Object { $_.Status -eq 'Stopped' -and $_.StartType -eq 'Automatic' }`",
            "`Get-Process | Stop-Service -StartType Automatic`",
            "`Set-Service -Status Stopped | Select-Object Automatic`",
            "`Get-Service -Running | Sort-Object Automatic`",
            "`net start | findstr Stopped Automatic`"],
      gab="A",
      com="**Gabarito: A.** `Get-Service` devolve objetos de serviço; `Where-Object` filtra pelas propriedades `Status` (Stopped) e `StartType` (Automatic). Cmdlets seguem o padrão Verbo-Substantivo e o pipeline passa **objetos**.\n\n(B) `Get-Process` lista processos, não serviços, e o comando tentaria parar serviços. (C) `Set-Service` altera um serviço; não lista. (D) `Get-Service` não tem o parâmetro `-Running`. (E) `net start` lista apenas serviços em execução.\n\nObs.: PowerShell não está instalado no container de verificação; sintaxe conferida na documentação dos cmdlets."),

    Q(E, "04", 12, sub="12.3", k="so-rhel-firewalld", mv="D",
      enun="Em um servidor Red Hat Enterprise Linux 9 recém-instalado, o administrador precisa instalar o Apache HTTP Server, deixá-lo ativo e configurado para iniciar no boot, e liberar HTTPS no firewall de forma persistente. A sequência de comandos adequada é",
      alts=["`apt install apache2`; `service apache2 start`; `ufw allow 443`.",
            "`dnf install httpd`; `systemctl enable --now httpd`; `firewall-cmd --permanent --add-service=https` seguido de `firewall-cmd --reload`.",
            "`yum remove httpd`; `systemctl disable httpd`; `iptables -F`.",
            "`rpm -e httpd`; `chkconfig httpd off`; `firewall-cmd --add-port=80/udp`.",
            "`dnf install apache2`; `systemctl start apache2`; `setenforce 0`."],
      gab="B",
      com="**Gabarito: B.** Na família Red Hat o pacote é `httpd`, instalado com `dnf` (ou `yum`); `systemctl enable --now` ativa no boot e inicia; o firewalld libera serviços com `firewall-cmd --permanent --add-service=https` e `--reload` para aplicar a regra permanente.\n\n(A) `apt`, `apache2` e `ufw` são da família Debian/Ubuntu. (C) e (D) Removem ou desabilitam o serviço; `iptables -F` apaga todas as regras. (E) No RHEL o pacote não se chama apache2, e desativar o SELinux (`setenforce 0`) é contra o hardening."),

    Q(E, "04", 12, sub="12.4", k="so-hardening",
      enun="São medidas de hardening (endurecimento) de servidores Linux e Windows Server, EXCETO:",
      alts=["desabilitar o login direto do root via SSH (`PermitRootLogin no`) e usar autenticação por chave.",
            "remover pacotes, serviços e protocolos desnecessários, como o SMBv1.",
            "preferir a instalação Server Core no Windows Server, quando possível, para reduzir a superfície de ataque.",
            "manter o SELinux em modo enforcing e aplicar atualizações de segurança regularmente.",
            "aplicar `chmod 777` nos diretórios de aplicação para evitar falhas de permissão."],
      gab="E",
      com="**Gabarito: E.** `chmod 777` dá leitura, escrita e execução a todos: é o oposto do hardening e do princípio do menor privilégio.\n\n(A) Bloquear root via SSH e usar chaves reduz ataques de força bruta. (B) Menos serviços, menos superfície de ataque (o SMBv1 foi explorado pelo WannaCry). (C) O Server Core tem menor superfície de ataque e menos atualizações. (D) MAC com SELinux e patches em dia são controles básicos."),
]
